public class RateService {
    /**
     * Quote source that holds the settlement reference rate in fxq 3.4.1. On business days it equals the default
     * source; on vendor holidays the default source only repeats the previous business day's value (marked {@code ~N}).
     * Verified against partner statements for 10/03-10/05. Source 2 is a different quote here and must not be used.
     */
    static final int SETTLEMENT_SRC = 3;

    private final FxqClient client;
    private final Map<String, FxQuote> cache = new HashMap<>();
    private final Map<String, BigDecimal> settlementCache = new HashMap<>();
    private int vendorCalls;

    public RateService(FxqClient client) {
        this.client = client;
    }

    /** Display quote on the default source, as shown to customers. */
    public FxQuote quote(String currency, LocalDate date) {
        String pair = CurrencyPairs.pairOf(currency);
        return cache.computeIfAbsent(pair + "@" + date, k -> FxqClient.parse(fetch(pair, date, null)));
    }

    /** Rate applied to card transactions of the given KST settlement date. */
    public BigDecimal settlementRate(String currency, LocalDate date) {
        String pair = CurrencyPairs.pairOf(currency);
        return settlementCache.computeIfAbsent(pair + "@" + date, k -> settlementQuote(pair, date));
    }

    private BigDecimal settlementQuote(String pair, LocalDate date) {
        String line = fetch(pair, date, null);
        if (FxqClient.isStale(line)) {
            line = fetch(pair, date, SETTLEMENT_SRC);
            if (FxqClient.isStale(line)) {
                throw new IllegalStateException("no settlement rate for " + pair + " " + date + ": " + line);
            }
        }
        return FxqClient.parse(line).rate();
    }

    private String fetch(String pair, LocalDate date, Integer src) {
        vendorCalls++;
        return client.rate(pair, date, src);
    }

